{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Melagatran, a polar peptidomimetic with multiple ionizable groups, has human oral bioavailability of only 0.9–7%, showing that such structures undergo severe absorption/first-pass limitations; its very high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Remikiren, a peptidomimetic with multiple amide bonds and lipophilic/heteroaromatic elements, has absolute oral bioavailability of only 0.2–0.3% in humans across multiple doses; the high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "DX-9065a, a non-peptidic small molecule with basic amidino groups and aromatic/lactam-like features, has human oral bioavailability of only 2–3%, attributed to strong basic groups; the high transfer score supports low F for the query, which also contains basic amines and heteroaromatic/lactam motifs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Nintedanib, a complex heteroaromatic molecule with amide/ester and basic amine moieties, has absolute oral bioavailability around 5% in humans; the high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A related heteroaromatic amide with a basic pyrrolidine side chain shows oral bioavailability of about 10% or less in humans, reinforcing that this compound class is absorption-limited; the high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show low absolute oral bioavailability in humans (roughly 0.2–10%), and none support F ≥ 20%. The query's peptidomimetic, polar, heteroaromatic, and basic-amine features are consistent with extensive absorption/first-pass limitations, so low bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "Some analogues contain extreme ionizable groups such as amidines or carboxylates that may be more absorption-limited than the query, although the query's multiple basic amines and amide/urea motifs still favor low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

